def get_row(lst, x):
    result = []
    for i, row in enumerate(lst):
        try:
            j = row.index(x)
            if not any(y >= j for y in result):
                result.append((i, j))
        except ValueError:
            pass
    result.sort(key=lambda x: (x[0], -x[1]))
    return result
```

